{% extends "templates/print/ph_basis.html" %}
{% block titel %}Bestellbestätigung {{ doc.name }}{% endblock %}
{% block kopfrechts %}Bestellung {{ doc.name }}<br>{{ ph_datum(doc.angelegt) }}<br>{% if doc.modus == 'test' %}<span class="ph-test">TESTBESTELLUNG</span>{% else %}Status {{ _(doc.status) }}{% endif %}{% endblock %}
{% block inhalt %}
<h1>Bestellbestätigung</h1>
<p>Guten Tag {{ doc.kunde_name }},<br>vielen Dank für Ihre Bestellung. Hiermit nehmen wir sie an und bestätigen den Vertrag (Bestellnummer {{ doc.name }}, bestellt am {{ ph_datum(doc.angelegt) }}).</p>
<table class="ph-tabelle"><thead><tr><th>Artikel</th><th class="zahl">Menge</th><th class="zahl">Einzelpreis</th><th class="zahl">Summe</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ p.marke or "" }} {{ p.bezeichnung }}{% if p.variante_name %} – {{ p.variante_name }}{% endif %}<br><span style="color:#6b7280;font-size:8pt">inkl. {{ (p.ust_satz_promille or 0) / 100 }} % USt.</span></td><td class="zahl">{{ p.menge }}</td><td class="zahl">{{ ph_betrag(p.einzel_cent) }}</td><td class="zahl">{{ ph_betrag(p.summe_cent) }}</td></tr>{% endfor %}
<tr><td colspan="3">Waren</td><td class="zahl">{{ ph_betrag(doc.waren_cent) }}</td></tr>
<tr><td colspan="3">Versand{% if doc.lieferart == 'abholung' %} (Abholung im Showroom){% endif %}</td><td class="zahl">{{ ph_betrag(doc.versand_cent) }}</td></tr>
<tr class="ph-summe"><td colspan="3">Gesamtpreis (inkl. {{ ph_betrag(doc.ust_cent) }} USt.)</td><td class="zahl">{{ ph_betrag(doc.gesamt_cent) }}</td></tr>
</tbody></table>
{% if doc.ust_aufteilung|length > 1 %}<p style="font-size:8pt;color:#6b7280">Enthaltene USt: {% for u in doc.ust_aufteilung %}{{ u.satz_promille / 100 }} % auf {{ ph_betrag(u.brutto_cent) }} = {{ ph_betrag(u.ust_cent) }}{% if not loop.last %} · {% endif %}{% endfor %}</p>{% endif %}
<h2>Lieferung und Zahlung</h2>
<div class="ph-feld"><b>Lieferung</b> {% if doc.lieferart == 'abholung' %}Abholung im Showroom {{ firma.ort }}. Wir melden uns per E-Mail, sobald Ihre Artikel abholbereit sind.{% if doc.abholung_bis %} Bitte bis {{ ph_datum(doc.abholung_bis) }} abholen.{% endif %}{% else %}Versand an {{ doc.adresse_strasse }} {{ doc.adresse_hausnr }}, {{ doc.adresse_plz }} {{ doc.adresse_ort }}, {{ doc.adresse_land }}{% if doc.versichert %} (versichert){% endif %}{% endif %}</div>
<div class="ph-feld"><b>Zahlung</b> {% if doc.zahlung == 'vorort' %}Zahlung bei Abholung im Showroom.{% else %}Online bezahlt über Stripe{% if doc.bezahlt_am %} am {{ ph_datum(doc.bezahlt_am) }}{% endif %}.{% endif %}</div>
<h2>Verkäufer</h2>
<p>{{ firma.firmenname }} („{{ firma.marke }}“), {{ firma.strasse }}, {{ firma.plz }} {{ firma.ort }} · {{ firma.telefon or "" }} · {{ firma.email }}{% if firma.firmenbuchnummer %} · {{ firma.firmenbuchnummer }}{% endif %}{% if firma.uid %} · UID {{ firma.uid }}{% endif %}</p>
{% set einstShop = frappe.get_cached_doc("PH Shop Einstellungen") %}
{% if einstShop.gewaehrleistung_text %}<p class="ph-hinweis">{{ einstShop.gewaehrleistung_text }}</p>{% endif %}
<h2>Widerrufsbelehrung</h2>
<div style="font-size:8.5pt">{{ einstShop.widerrufsbelehrung_text or "Widerrufsbelehrung (Stand " ~ ph_datum(doc.widerrufsbelehrung_stand) ~ ") – Text in PH Shop Einstellungen hinterlegen." }}</div>
<h2>Allgemeine Geschäftsbedingungen</h2>
<div style="font-size:8.5pt">{{ einstShop.agb_text or "AGB (Stand " ~ ph_datum(doc.agb_stand) ~ ") – Text in PH Shop Einstellungen hinterlegen." }}</div>
{% endblock %}
{% block fuss %}<div>AGB Stand {{ ph_datum(doc.agb_stand) }} · Widerrufsbelehrung Stand {{ ph_datum(doc.widerrufsbelehrung_stand) }}</div>{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set einstShop = frappe.get_cached_doc("PH Shop Einstellungen") %}
{% block titel %}Gutschein {{ doc.name }}{% endblock %}
{% block css %}
.gs-karte { border: 1px solid #d9d4cc; padding: 14mm 12mm; margin: 6mm 0; text-align: center; background: {% if doc.motiv == 'seelicht' %}linear-gradient(180deg, #ffffff 0 62%, #e9e4db 62% 63%, #ffffff 63%){% else %}#fff{% endif %}; }
.gs-marke { font-family: "Bodoni Moda", Georgia, serif; font-size: 30pt; letter-spacing: .22em; }
.gs-geweih { font-size: 26pt; color: #8a7a66; margin-bottom: 3mm; }
.gs-wert { font-family: "Bodoni Moda", Georgia, serif; font-size: 40pt; margin: 8mm 0 2mm; }
.gs-code { font-family: "Courier New", monospace; font-size: 16pt; letter-spacing: .14em; border: 1px dashed #30373e; display: inline-block; padding: 3mm 6mm; margin: 6mm 0; }
.gs-widmung { font-size: 11pt; margin: 4mm 0; }
.gs-gruss { font-style: italic; color: #4b5563; white-space: pre-line; }
.gs-klein { font-size: 8pt; color: #6b7280; }
{% endblock %}
{% block kopfrechts %}Gutschein {{ doc.name }}<br>ausgestellt {{ ph_datum(doc.ausgegeben_am) }}{% if doc.test %}<br><span class="ph-test">TEST – NICHT EINLÖSBAR</span>{% endif %}{% endblock %}
{% block inhalt %}
<div class="gs-karte">
  {% if doc.motiv == 'geweih' %}<div class="gs-geweih">&#x2698;</div>{% endif %}
  <div class="gs-marke">PLATZHIRSCH</div>
  <div class="ph-untertitel">Home Living · Gutschein</div>
  <div class="gs-wert">{{ ph_betrag(doc.wert_cent) }}</div>
  {% if doc.empfaenger %}<div class="gs-widmung">für {{ doc.empfaenger }}</div>{% endif %}
  {% if doc.grusstext %}<div class="gs-gruss">{{ doc.grusstext }}</div>{% endif %}
  <div class="gs-code">{{ doc.code_klartext if doc.code_klartext else "…" ~ doc.code_letzte4 }}</div>
  <div class="gs-klein">{% if doc.gueltig_bis %}Gültig bis {{ ph_datum(doc.gueltig_bis) }}{% else %}Unbefristet gültig{% endif %} · einlösbar im Showroom {{ firma.ort }} und im Onlineshop, auch in Teilbeträgen · Code wie Bargeld behandeln</div>
</div>
<p class="gs-klein">Gutscheinbedingungen (Stand {{ ph_datum(doc.bedingungen_stand) }}): {{ einstShop.gutschein_bedingungen_url }} · Aussteller {{ firma.firmenname }} · Gutschein-Nr. {{ doc.name }}</p>
{% endblock %}
{% block fuss %}{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}{% if doc.art == 'Erstattung' %}Rückerstattungsbeleg{% else %}Zahlungsbeleg{% endif %} {{ doc.name }}{% endblock %}
{% block kopfrechts %}{{ doc.name }}<br>{{ ph_datum(doc.zeitpunkt) }}{% if not doc.livemode and doc.kanal.startswith('Stripe') %}<br><span class="ph-test">TESTZAHLUNG</span>{% endif %}{% endblock %}
{% block inhalt %}
<h1>{% if doc.art == 'Erstattung' %}Rückerstattungsbeleg{% else %}Zahlungsbeleg{% endif %}</h1>
<div class="ph-feld"><b>Betrag</b> {% if doc.art == 'Erstattung' %}−{% endif %}{{ ph_betrag(doc.betrag_cent, doc.waehrung) }}</div>
<div class="ph-feld"><b>Art</b> {{ _(doc.art) }} · {{ _(doc.kanal) }}</div>
<div class="ph-feld"><b>Zeitpunkt</b> {{ frappe.format(doc.zeitpunkt, {"fieldtype": "Datetime"}) }}</div>
{% if doc.bezug %}<div class="ph-feld"><b>Bezug</b> {{ _(doc.bezug_doctype) }} {{ doc.bezug }}</div>{% endif %}
{% if doc.zahlungsreferenz %}<div class="ph-feld"><b>Referenz</b> {{ doc.zahlungsreferenz }}</div>{% endif %}
{% if doc.ursprung %}<div class="ph-feld"><b>Ursprungszahlung</b> {{ doc.ursprung }}</div>{% endif %}
{% if doc.stripe_payment_intent %}<div class="ph-feld"><b>Stripe</b> {{ doc.stripe_payment_intent }}{% if doc.stripe_refund %} · Refund {{ doc.stripe_refund }}{% endif %}</div>{% endif %}
{% if doc.art == 'Erstattung' and doc.notiz %}<div class="ph-feld"><b>Grund</b> {{ doc.notiz }}</div>{% endif %}
{% if doc.erstattungen %}<h2>Erstattungen zu dieser Zahlung</h2><table class="ph-tabelle"><thead><tr><th>Datum</th><th>Grund</th><th class="zahl">Betrag</th></tr></thead><tbody>{% for e in doc.erstattungen %}<tr><td>{{ ph_datum(e.zeitpunkt) }}</td><td>{{ e.grund or "" }}</td><td class="zahl">{{ ph_betrag(e.betrag_cent) }}</td></tr>{% endfor %}</tbody></table>{% endif %}
<p class="ph-hinweis">{% if doc.art == 'Erstattung' %}Die Rückzahlung erfolgt über das ursprüngliche Zahlungsmittel; bei Kartenzahlungen kann die Gutschrift einige Bankarbeitstage dauern.{% else %}Dieser Beleg ist keine Rechnung. Die Rechnung senden wir gesondert.{% endif %}</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Eingangsbestätigung Widerruf {{ doc.eingangsnummer or doc.name }}{% endblock %}
{% block kopfrechts %}Eingangsnummer {{ doc.eingangsnummer or doc.name }}<br>{{ frappe.format(doc.eingegangen_am, {"fieldtype": "Datetime"}) }}{% endblock %}
{% block inhalt %}
<h1>Eingangsbestätigung Ihres Widerrufs</h1>
<p>Guten Tag {{ doc.kunde_name }},<br>wir bestätigen den Eingang Ihres Widerrufs am {{ frappe.format(doc.eingegangen_am, {"fieldtype": "Datetime"}) }} (Eingangsnummer {{ doc.eingangsnummer or doc.name }}).</p>
<h2>Inhalt Ihrer Erklärung</h2>
<pre style="font-family:inherit;white-space:pre-wrap">{{ doc.erklaerung_text() }}</pre>
{% if doc.bestellung %}<p>Bitte senden Sie die Waren binnen 14 Tagen (bis {{ ph_datum(doc.rueckgabe_bis) }}) an uns zurück oder übergeben Sie sie im Showroom. Wir erstatten alle Zahlungen einschließlich der Lieferkosten (Standardlieferung) spätestens binnen 14 Tagen über das ursprüngliche Zahlungsmittel, sobald wir die Waren zurückerhalten oder Ihren Nachweis der Rücksendung haben.</p>{% else %}<p>Wir prüfen den Widerruf und zahlen den Betrag spätestens binnen 14 Tagen über das ursprüngliche Zahlungsmittel zurück. Noch nicht eingelöste Gutscheincodes dieser Bestellung sind gesperrt.</p>{% endif %}
<p>{{ firma.firmenname }} („{{ firma.marke }}“), {{ firma.strasse }}, {{ firma.plz }} {{ firma.ort }} · Telefon {{ firma.telefon or "" }} · {{ firma.email }}</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Retoure-Begleitschein {{ doc.name }}{% endblock %}
{% block kopfrechts %}Retoure {{ doc.name }}<br>Bestellung {{ doc.bestellung }}<br>{{ ph_datum(doc.angekuendigt_am) }}{% endblock %}
{% block inhalt %}
<h1>Retoure-Begleitschein</h1>
<p>Bitte legen Sie diesen Schein der Rücksendung bei oder bringen Sie ihn zur Rückgabe im Showroom mit.</p>
<div class="ph-feld"><b>Bestellung</b> {{ doc.bestellung }}</div>
{% if doc.widerruf %}<div class="ph-feld"><b>Widerruf</b> {{ doc.widerruf }}</div>{% endif %}
<table class="ph-tabelle"><thead><tr><th>Artikel</th><th class="zahl">Menge</th><th>Zustand (vom Team auszufüllen)</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ p.bezeichnung or p.slug }}</td><td class="zahl">{{ p.menge }}</td><td>☐ neu &nbsp; ☐ geöffnet &nbsp; ☐ beschädigt</td></tr>{% endfor %}
</tbody></table>
<h2>Rücksendeadresse</h2>
<p>{{ firma.firmenname }} – Retoure {{ doc.name }}<br>{{ firma.strasse }}<br>{{ firma.plz }} {{ firma.ort }}, {{ firma.land }}</p>
<p class="ph-hinweis">Die Rücksendung muss binnen 14 Tagen ab Widerruf erfolgen. Bitte verpacken Sie zerbrechliche Artikel sorgfältig; für eine Wertminderung durch unsachgemäßen Umgang haften Sie nach § 15 Abs 4 FAGG.</p>
{% endblock %}
